insert into public.editor_notes (ref, note) values
  ('SYNPTCL/LOC/001', 'Codex Doc status: Draft. Expanded and checked against the manuscript, 8 November 2026. Awaiting David''s review.'),
  ('SYNPTCL/LOC/002', 'Codex Doc status: Draft. Expanded and checked against the manuscript, 8 November 2026. Awaiting David''s review.'),
